CREATE TABLE public.clinician_cases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), patient_id uuid NOT NULL REFERENCES public.clinician_patients(id), created_by uuid NOT NULL DEFAULT auth.uid(), title text NOT NULL, category text NOT NULL CHECK(category IN ('Rosacea','Acne','Aesthetic treatment','Post-procedure','Other')), opened_date date NOT NULL, follow_up_date date, summary text NOT NULL DEFAULT '', outcomes text NOT NULL DEFAULT '', archived boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.clinician_cases TO authenticated; GRANT ALL ON public.clinician_cases TO service_role;
ALTER TABLE public.clinician_cases ENABLE ROW LEVEL SECURITY;
CREATE POLICY case_read ON public.clinician_cases FOR SELECT TO authenticated USING(public.can_access_clinician_patient(patient_id));
CREATE POLICY case_insert ON public.clinician_cases FOR INSERT TO authenticated WITH CHECK(public.can_access_clinician_patient(patient_id) AND created_by=auth.uid());
CREATE POLICY case_update ON public.clinician_cases FOR UPDATE TO authenticated USING(public.can_access_clinician_patient(patient_id)) WITH CHECK(public.can_access_clinician_patient(patient_id) AND created_by=auth.uid());
CREATE INDEX clinician_cases_patient ON public.clinician_cases(patient_id,opened_date);
ALTER TABLE public.clinician_photos ADD COLUMN case_id uuid REFERENCES public.clinician_cases(id), ADD COLUMN treatment_id uuid REFERENCES public.clinician_treatments(id), ADD COLUMN tags text[] NOT NULL DEFAULT '{}', ADD COLUMN session_name text NOT NULL DEFAULT '', ADD COLUMN archived boolean NOT NULL DEFAULT false;
ALTER TABLE public.clinician_treatments ADD COLUMN case_id uuid REFERENCES public.clinician_cases(id);
ALTER TABLE public.clinician_notes ADD COLUMN case_id uuid REFERENCES public.clinician_cases(id);
ALTER TABLE public.clinician_checkins ADD COLUMN case_id uuid REFERENCES public.clinician_cases(id);
CREATE TABLE public.clinician_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), patient_id uuid NOT NULL REFERENCES public.clinician_patients(id), case_id uuid NOT NULL REFERENCES public.clinician_cases(id), treatment_id uuid REFERENCES public.clinician_treatments(id), uploaded_by uuid NOT NULL DEFAULT auth.uid(), storage_path text NOT NULL UNIQUE, file_name text NOT NULL, document_date date NOT NULL, tags text[] NOT NULL DEFAULT '{}', note text NOT NULL DEFAULT '', archived boolean NOT NULL DEFAULT false, is_test boolean NOT NULL DEFAULT true CHECK(is_test), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.clinician_documents TO authenticated; GRANT ALL ON public.clinician_documents TO service_role;
ALTER TABLE public.clinician_documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY document_read ON public.clinician_documents FOR SELECT TO authenticated USING(public.can_access_clinician_patient(patient_id));
CREATE POLICY document_insert ON public.clinician_documents FOR INSERT TO authenticated WITH CHECK(public.can_access_clinician_patient(patient_id) AND uploaded_by=auth.uid() AND storage_path LIKE auth.uid()::text || '/' || patient_id::text || '/%');
CREATE POLICY document_update ON public.clinician_documents FOR UPDATE TO authenticated USING(public.can_access_clinician_patient(patient_id)) WITH CHECK(public.can_access_clinician_patient(patient_id) AND uploaded_by=auth.uid() AND storage_path LIKE auth.uid()::text || '/' || patient_id::text || '/%');
CREATE TABLE public.clinician_case_updates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), patient_id uuid NOT NULL REFERENCES public.clinician_patients(id), case_id uuid NOT NULL REFERENCES public.clinician_cases(id), recorded_by uuid NOT NULL DEFAULT auth.uid(), event_date date NOT NULL, event_type text NOT NULL CHECK(event_type IN ('Consultation','Follow-up','Observation','Outcome')), content text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.clinician_case_updates TO authenticated; GRANT ALL ON public.clinician_case_updates TO service_role;
ALTER TABLE public.clinician_case_updates ENABLE ROW LEVEL SECURITY;
CREATE POLICY update_read ON public.clinician_case_updates FOR SELECT TO authenticated USING(public.can_access_clinician_patient(patient_id));
CREATE POLICY update_insert ON public.clinician_case_updates FOR INSERT TO authenticated WITH CHECK(public.can_access_clinician_patient(patient_id) AND recorded_by=auth.uid());
CREATE FUNCTION public.validate_clinician_case_link() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
IF TG_OP='UPDATE' AND NEW.patient_id<>OLD.patient_id THEN RAISE EXCEPTION 'Patient association cannot change'; END IF;
IF NEW.case_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.clinician_cases c WHERE c.id=NEW.case_id AND c.patient_id=NEW.patient_id) THEN RAISE EXCEPTION 'Case must belong to authorized patient'; END IF;
IF TG_TABLE_NAME IN ('clinician_photos','clinician_documents') THEN
IF NEW.treatment_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.clinician_treatments t WHERE t.id=NEW.treatment_id AND t.patient_id=NEW.patient_id AND t.case_id IS NOT DISTINCT FROM NEW.case_id) THEN RAISE EXCEPTION 'Treatment must belong to same patient and case'; END IF;
END IF;
RETURN NEW; END $$;
CREATE TRIGGER case_link BEFORE INSERT OR UPDATE ON public.clinician_photos FOR EACH ROW EXECUTE FUNCTION public.validate_clinician_case_link();
CREATE TRIGGER case_link BEFORE INSERT OR UPDATE ON public.clinician_documents FOR EACH ROW EXECUTE FUNCTION public.validate_clinician_case_link();
CREATE TRIGGER case_link BEFORE INSERT OR UPDATE ON public.clinician_notes FOR EACH ROW EXECUTE FUNCTION public.validate_clinician_case_link();
CREATE TRIGGER case_link BEFORE INSERT OR UPDATE ON public.clinician_treatments FOR EACH ROW EXECUTE FUNCTION public.validate_clinician_case_link();
CREATE TRIGGER case_link BEFORE INSERT OR UPDATE ON public.clinician_checkins FOR EACH ROW EXECUTE FUNCTION public.validate_clinician_case_link();
CREATE TRIGGER case_link BEFORE INSERT OR UPDATE ON public.clinician_case_updates FOR EACH ROW EXECUTE FUNCTION public.validate_clinician_case_link();
CREATE FUNCTION public.validate_clinician_case_owner() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND (NEW.patient_id<>OLD.patient_id OR NEW.created_by<>OLD.created_by) THEN RAISE EXCEPTION 'Case ownership cannot change'; END IF; RETURN NEW; END $$;
CREATE TRIGGER case_owner BEFORE UPDATE ON public.clinician_cases FOR EACH ROW EXECUTE FUNCTION public.validate_clinician_case_owner();
CREATE OR REPLACE FUNCTION public.validate_clinician_checkin() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE concern_value text; metric text; value jsonb; allowed text[]; BEGIN IF NEW.case_id IS NOT NULL THEN SELECT category INTO concern_value FROM public.clinician_cases WHERE id=NEW.case_id AND patient_id=NEW.patient_id; ELSE SELECT concern INTO concern_value FROM public.clinician_patients WHERE id=NEW.patient_id; END IF; allowed=CASE concern_value WHEN 'Rosacea' THEN ARRAY['Redness','Flushing episodes','Burning or stinging','Dryness','Skin sensitivity'] WHEN 'Acne' THEN ARRAY['Breakouts','Irritation','Dryness','Treatment adherence'] WHEN 'Post-procedure' THEN ARRAY['Discomfort','Redness','Dryness'] ELSE ARRAY['Discomfort','Dryness','Sensitivity'] END; IF jsonb_typeof(NEW.ratings)<>'object' OR NEW.ratings='{}'::jsonb THEN RAISE EXCEPTION 'Subjective ratings required'; END IF; FOR metric,value IN SELECT * FROM jsonb_each(NEW.ratings) LOOP IF NOT metric=ANY(allowed) OR jsonb_typeof(value)<>'number' THEN RAISE EXCEPTION 'Invalid subjective metric'; END IF; IF (value::text)::numeric < 0 OR (value::text)::numeric > 4 OR (value::text)::numeric <> trunc((value::text)::numeric) THEN RAISE EXCEPTION 'Subjective rating must be 0 to 4'; END IF; END LOOP; RETURN NEW; END $$;
CREATE POLICY clinician_document_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='clinician-test-documents' AND (storage.foldername(name))[1]=auth.uid()::text AND public.can_access_clinician_patient(((storage.foldername(name))[2])::uuid));
CREATE POLICY clinician_document_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='clinician-test-documents' AND (storage.foldername(name))[1]=auth.uid()::text AND public.can_access_clinician_patient(((storage.foldername(name))[2])::uuid) AND lower(storage.extension(name)) IN ('pdf','txt','jpg','jpeg','png','webp'));
CREATE POLICY clinician_document_cleanup ON storage.objects FOR DELETE TO authenticated USING(bucket_id='clinician-test-documents' AND (storage.foldername(name))[1]=auth.uid()::text AND public.can_access_clinician_patient(((storage.foldername(name))[2])::uuid) AND NOT EXISTS(SELECT 1 FROM public.clinician_documents d WHERE d.storage_path=name));
COMMENT ON TABLE public.clinician_cases IS 'Archive retains all linked records and storage objects. Permanent deletion is not an archival action.';
CREATE INDEX clinician_documents_case ON public.clinician_documents(case_id,document_date);
CREATE INDEX clinician_photos_case ON public.clinician_photos(case_id,capture_date);
CREATE INDEX clinician_case_updates_case ON public.clinician_case_updates(case_id,event_date);